    async def get_group_members_async(
        self,
        id: str,
        top: Optional[int] = None,
        *,
        timeout: Optional[float] = None,
        headers: Optional[Mapping[str, str]] = None,
        client_request_id: Optional[str] = None,
        response_hook: Optional[ConnectorResponseHook] = None,
    ) -> AsyncIterator[dict[str, Any]]:
        """
        Get group members

        Get the users who are members of a group. You can query up to 1000
        items using the Top parameter. If you need to retrieve more than 1000
        values, please turn on the Settings->Pagination feature and provide a
        Threshold limit.

        Yields items from every response page and automatically follows the
        connector continuation URL.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v1.0/groups/{quote(str(id), safe='')}/members"
        )
        query_params = []
        if top is not None:
            value = str(top)
            if isinstance(top, bool):
                value = value.lower()
            query_params.append(f"$top={quote(value, safe='')}")
        if query_params:
            request_url += '?' + '&'.join(query_params)
        request_body = None

        while True:
            response = await self.http_client.send_async(
                "GET", request_url, body=request_body,
                timeout=timeout,
                headers=headers,
                client_request_id=client_request_id,
                response_hook=response_hook,
            )

            if not (200 <= response.status < 300):
                raise ConnectorException(
                    "GET",
                    request_url,
                    response.status,
                    response.text,
                )

            if not response.text:
                return

            page = json.loads(response.text)
            for item in page.get("value", []):
                yield item

            next_link = page.get("@odata.nextLink")
            if not next_link:
                return

            request_url = self._resolve_pagination_url(next_link, request_url)
            request_body = None

